<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import DashboardLayout from '../layouts/DashboardLayout.vue';
import AppIcon from '../components/AppIcon.vue';
import { schoolHref } from '../navigation';
import type { School, Plan, SchoolDashboard } from '../types';
type RecordRow = Record<string, any>;
interface Field { key: string; label: string; type: string; source?: string; options?: string[] }
interface Option { id: number; label: string; academic_class_id?: number }
const props = defineProps<{ page:string; resource:string; title:string; mode:string; record:RecordRow|null; rows:{data:RecordRow[];total:number;from:number|null;to:number|null;links:{url:string|null;label:string;active:boolean}[]}; fields:Field[]; options:Record<string,Option[]>; filters:Record<string,string>; history:RecordRow[]; assignments:RecordRow[]; baseUrl:string; schools:School[]; selectedSchool:School|null; dashboard:SchoolDashboard|null; plans:Plan[]; flash:{success?:string} }>();
const defaults:RecordRow = {};
props.fields.forEach(field=>{ defaults[field.key] = props.record?.[field.key] ?? (field.type==='checkbox' ? field.key==='active' : field.type==='number' ? (field.key==='grade_level'?1:field.key==='capacity'?'':0) : field.options?.[0] ?? ''); });
const form = useForm(defaults);
const query=ref(props.filters.q??''), status=ref(props.filters.status??''), session=ref(props.filters.academic_session_id??''), klass=ref(props.filters.academic_class_id??'');
const errorSummary=computed(()=>Object.values(form.errors));
const deleting=ref<RecordRow|null>(null), deleteForm=useForm<Record<string,string>>({});
const changeRecord=ref<RecordRow|null>(null);
const change=useForm({operation:'transfer',academic_session_id:'',academic_class_id:'',section_id:'',started_on:''});
const formMode=computed(()=>['create','edit'].includes(props.mode));
const statusOptions=computed(()=>props.resource==='teachers'?['active','on_leave','inactive']:props.resource==='students'?['active','inactive','graduated','archived']:props.resource==='enrollments'?['active','transferred','promoted','completed','withdrawn']:['active','inactive']);
const primaryKey = (row:RecordRow) => row.full_name ?? row.name ?? row.student?.full_name ?? row.teacher?.full_name ?? row.academic_class?.name ?? `Record ${row.id}`;
const secondary = (row:RecordRow) => row.admission_number ?? row.employee_code ?? row.code ?? row.subject?.name ?? row.academic_session?.name ?? '';
function filter() { router.get(props.baseUrl,{q:query.value,status:status.value,academic_session_id:session.value,academic_class_id:klass.value},{preserveState:true,replace:true}); }
function fieldOptions(field:Field):Option[] { const values=props.options[field.source??'']??[]; return field.key==='section_id' && form.academic_class_id ? values.filter(o=>o.academic_class_id==form.academic_class_id) : values; }
function submit() { if(props.mode==='edit' && props.record) form.put(`${props.baseUrl}/${props.record.id}`); else form.post(props.baseUrl); }
function remove() { if(deleting.value) deleteForm.delete(`${props.baseUrl}/${deleting.value.id}`,{onSuccess:()=>deleting.value=null}); }
function startChange(row:RecordRow) {changeRecord.value=row;change.reset();change.academic_session_id=String(row.academic_session_id);change.academic_class_id=String(row.academic_class_id);change.section_id='';change.started_on=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Karachi'});}
function submitChange(){if(changeRecord.value)change.post(`${props.baseUrl}/${changeRecord.value.id}/change`,{onSuccess:()=>changeRecord.value=null});}
const classOptions=computed(()=>props.options.sections?.filter(o=>!change.academic_class_id || o.academic_class_id==Number(change.academic_class_id))??[]);
</script>
<template>
<Head :title="title"/>
<DashboardLayout :page="resource==='sessions'?'academics':resource" :title="title" :schools="schools" :selected-school="selectedSchool" :dashboard="dashboard">
    <div class="academic-local-note"><AppIcon name="info" :size="15"/><span>LOCAL ACADEMIC WORKSPACE · Changes are saved to this demo school's database. Academic data below is live; finance remains sample data.</span></div>
    <div class="page-heading"><div><h1>{{ mode==='create' ? (resource==='students'?'Student Admission':`Create ${title}`) : mode==='edit' ? `Edit ${title}` : title }}</h1><p>{{ selectedSchool?.name }} · School-scoped academic records</p></div><div class="academic-actions"><Link v-if="mode!=='index'" :href="baseUrl" class="secondary-button">Back to directory</Link><Link v-if="mode==='index'" :href="baseUrl+'/create'" class="academic-button"><AppIcon name="plus" :size="15"/>{{ resource==='students'?'Admit student':'Create record' }}</Link><Link v-if="mode==='show' && record && !record.deleted_at && resource!=='enrollments' && !record?.deleted_at" :href="`${baseUrl}/${record.id}/edit`" class="academic-button">Edit record</Link></div></div>
    <div v-if="flash.success" class="success-message" role="status"><AppIcon name="check" :size="17"/>{{ flash.success }}</div>
    <div class="academic-tabs"><Link v-for="entry in [{key:'sessions',label:'Sessions'},{key:'classes',label:'Classes'},{key:'sections',label:'Sections'},{key:'subjects',label:'Subjects'},{key:'class-subjects',label:'Class subjects'},{key:'teachers',label:'Teachers'},{key:'teacher-assignments',label:'Assignments'},{key:'students',label:'Students'},{key:'enrollments',label:'Enrollments'}]" :key="entry.key" :class="{active:resource===entry.key}" :href="schoolHref(selectedSchool?.slug,entry.key)">{{ entry.label }}</Link></div>

    <section v-if="formMode" class="panel academic-form-panel"><div class="academic-form-header"><h2>{{ resource==='students'?'Admission details':'Record details' }}</h2><p v-if="resource==='students'">Admission number is allocated automatically and cannot be changed. Enroll the student after admission.</p><p v-else>Required fields are validated against the selected school.</p></div><form @submit.prevent="submit" novalidate><div v-if="errorSummary.length" class="error-summary" role="alert"><strong>Review the following:</strong><p v-for="error in errorSummary" :key="String(error)">{{ error }}</p></div><div class="academic-form-grid"><div v-for="field in fields" v-show="!(resource==='teacher-assignments' && field.key==='subject_id' && form.kind==='form_teacher')" :key="field.key" class="form-field" :class="{'checkbox-field':field.type==='checkbox'}"><label :for="field.key">{{ field.label }}</label><input v-if="field.type==='checkbox'" :id="field.key" v-model="form[field.key]" type="checkbox"/><select v-else-if="field.type==='select'" :id="field.key" v-model="form[field.key]" :aria-invalid="!!form.errors[field.key]" @change="field.key==='academic_class_id' ? form.section_id='' : field.key==='kind' && form.kind==='form_teacher' ? form.subject_id='' : null"><option value="">Select {{ field.label.toLowerCase() }}</option><option v-for="option in field.options" :key="option" :value="option">{{ option.replaceAll('_',' ') }}</option><option v-for="option in fieldOptions(field)" :key="option.id" :value="option.id">{{ option.label }}</option></select><input v-else :id="field.key" v-model="form[field.key]" :type="field.type" :aria-invalid="!!form.errors[field.key]" :min="field.type==='number'?0:undefined" :maxlength="field.type==='text'?150:undefined"/><p v-if="form.errors[field.key]" class="field-error">{{ form.errors[field.key] }}</p></div></div><div class="academic-form-footer"><Link :href="baseUrl" class="secondary-button">Cancel</Link><button type="submit" class="academic-button" :disabled="form.processing">{{ form.processing?'Saving…':'Save record' }}</button></div></form></section>

    <template v-else-if="mode==='show' && record"><section class="panel academic-profile"><div class="profile-heading"><span class="profile-symbol"><AppIcon :name="resource==='teachers'?'staff':resource==='students'?'students':'academics'" :size="28"/></span><div><h2>{{ primaryKey(record) }}</h2><p>{{ secondary(record) }}</p></div><span class="live-data-label">DATABASE RECORD</span></div><dl class="academic-details"><div v-for="field in fields" :key="field.key"><dt>{{ field.label }}</dt><dd>{{ field.type==='checkbox' ? (record?.[field.key]?'Yes':'No') : field.source ? (props.options[field.source]?.find(o=>o.id==record?.[field.key])?.label??'—') : (record?.[field.key]??'—') }}</dd></div></dl><div class="academic-actions"><button v-if="resource==='enrollments' && record.status==='active'" class="academic-button" @click="startChange(record)">Promote / transfer / withdraw</button><button v-if="resource!=='enrollments' && !record?.deleted_at" class="danger-button" @click="deleting=record">{{ resource==='students'?'Archive student':'Delete record' }}</button><Link v-if="resource==='students'" :href="schoolHref(selectedSchool?.slug,'enrollments')+'/create'" class="academic-button">Create enrollment</Link></div></section>
        <section v-if="resource==='students'" class="panel academic-history"><div class="panel-heading"><h2>Enrollment history</h2></div><div class="table-scroll"><table><thead><tr><th>Session</th><th>Class / Section</th><th>Period</th><th>Status</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td>{{ item.academic_session?.name }}</td><td>{{ item.academic_class?.name }} / {{ item.section?.name }}</td><td>{{ item.started_on }} → {{ item.ended_on??'Current' }}</td><td>{{ item.status }}</td></tr></tbody></table><p v-if="!history.length" class="academic-empty">No enrollments yet. Create the first enrollment to assign a session and section.</p></div></section>
        <section v-if="resource==='teachers'" class="panel academic-history"><div class="panel-heading"><h2>Teaching and form-teacher assignments</h2></div><div class="table-scroll"><table><thead><tr><th>Session</th><th>Class / Section</th><th>Subject / role</th></tr></thead><tbody><tr v-for="item in assignments" :key="item.id"><td>{{ item.academic_session?.name }}</td><td>{{ item.academic_class?.name }} / {{ item.section?.name }}</td><td>{{ item.subject?.name??'Form teacher' }}</td></tr></tbody></table><p v-if="!assignments.length" class="academic-empty">No assignments yet.</p></div><Link :href="schoolHref(selectedSchool?.slug,'teacher-assignments')+'/create'" class="card-footer-link">Create teacher assignment</Link></section>
    </template>

    <section v-else class="panel academic-directory"><form class="academic-filters" @submit.prevent="filter"><label class="academic-search"><AppIcon name="search" :size="16"/><input v-model="query" type="search" aria-label="Search academic records" placeholder="Search name or code…"/></label><select v-if="!['class-subjects','teacher-assignments'].includes(resource)" v-model="status" aria-label="Filter status"><option value="">All statuses</option><option v-for="value in statusOptions" :key="value">{{ value }}</option></select><select v-if="['enrollments','teacher-assignments'].includes(resource)" v-model="session" aria-label="Filter session"><option value="">All sessions</option><option v-for="o in options.sessions" :key="o.id" :value="o.id">{{ o.label }}</option></select><select v-if="['sections','class-subjects','enrollments','teacher-assignments'].includes(resource)" v-model="klass" aria-label="Filter class"><option value="">All classes</option><option v-for="o in options.classes" :key="o.id" :value="o.id">{{ o.label }}</option></select><button class="secondary-button" type="submit">Apply filters</button></form><div v-if="deleteForm.errors.record" class="error-summary" role="alert">{{ deleteForm.errors.record }}</div><div class="table-scroll"><table><thead><tr><th>Name / record</th><th>Code / session</th><th>Details</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows.data" :key="row.id"><td><Link class="academic-record-name" :href="`${baseUrl}/${row.id}`">{{ primaryKey(row) }}</Link></td><td>{{ secondary(row) }}</td><td>{{ row.section?.name ?? row.academic_class?.name ?? row.guardian_phone ?? row.email ?? (row.starts_on ? `${row.starts_on} → ${row.ends_on}` : row.grade_level!==undefined ? `Grade ${row.grade_level}` : row.classification ?? row.capacity ?? '—') }}</td><td><span class="status">{{ row.status ?? (row.is_current?'Current':row.active===false?'Inactive':'Active') }}</span></td><td><div class="row-actions"><Link :href="`${baseUrl}/${row.id}`">View</Link><Link v-if="resource!=='enrollments' && !row.deleted_at" :href="`${baseUrl}/${row.id}/edit`">Edit</Link><button v-if="resource==='enrollments' && row.status==='active'" @click="startChange(row)">Change</button><button v-if="resource!=='enrollments' && !row.deleted_at" class="delete-link" @click="deleting=row">{{ resource==='students'?'Archive':'Delete' }}</button></div></td></tr></tbody></table></div><div v-if="!rows.data.length" class="academic-empty"><AppIcon name="academics" :size="30"/><h2>No matching records</h2><p>Create your first record or adjust the search filters.</p></div><div class="academic-pagination"><span>{{ rows.from??0 }}–{{ rows.to??0 }} of {{ rows.total }}</span><nav aria-label="Pagination"><template v-for="(link,i) in rows.links" :key="i"><Link v-if="link.url" :href="link.url" :class="{active:link.active}" v-html="link.label"/><span v-else v-html="link.label"/></template></nav></div></section>

    <div v-if="deleting" class="academic-modal-overlay" @keydown.esc="deleting=null"><section class="academic-modal" role="dialog" aria-modal="true" aria-labelledby="delete-title"><h2 id="delete-title">{{ resource==='students'?'Archive student?':'Delete this record?' }}</h2><p>{{ primaryKey(deleting) }}. Records with dependent academic history cannot be deleted. Students are archived rather than permanently removed.</p><p v-if="deleteForm.errors.record" class="field-error">{{ deleteForm.errors.record }}</p><div class="academic-actions"><button class="secondary-button" @click="deleting=null">Cancel</button><button class="danger-button" :disabled="deleteForm.processing" @click="remove">{{ deleteForm.processing?'Working…':'Confirm' }}</button></div></section></div>
    <div v-if="changeRecord" class="academic-modal-overlay" @keydown.esc="changeRecord=null"><section class="academic-modal" role="dialog" aria-modal="true" aria-labelledby="change-title"><h2 id="change-title">Promotion and transfer</h2><p>{{ changeRecord.student?.full_name??'Selected student' }}. Previous enrollment records are preserved. Promotion requires a later session and a higher grade.</p><form @submit.prevent="submitChange"><div class="academic-form-grid"><div class="form-field"><label for="operation">Operation</label><select id="operation" v-model="change.operation"><option value="transfer">Transfer section</option><option value="promote">Promote to next session</option><option value="withdraw">Withdraw enrollment</option></select></div><div class="form-field"><label for="effective-date">Effective date</label><input id="effective-date" v-model="change.started_on" type="date"/></div><template v-if="change.operation!=='withdraw'"><div class="form-field"><label for="change-session">Target session</label><select id="change-session" v-model="change.academic_session_id"><option v-for="o in options.sessions" :key="o.id" :value="String(o.id)">{{ o.label }}</option></select></div><div class="form-field"><label for="change-class">Target class</label><select id="change-class" v-model="change.academic_class_id" @change="change.section_id=''"><option v-for="o in options.classes" :key="o.id" :value="String(o.id)">{{ o.label }}</option></select></div><div class="form-field"><label for="change-section">Target section</label><select id="change-section" v-model="change.section_id"><option value="">Select section</option><option v-for="o in classOptions" :key="o.id" :value="String(o.id)">{{ o.label }}</option></select></div></template></div><div v-if="Object.keys(change.errors).length" class="error-summary" role="alert"><p v-for="error in change.errors" :key="error">{{ error }}</p></div><div class="academic-form-footer"><button type="button" class="secondary-button" @click="changeRecord=null">Cancel</button><button class="academic-button" type="submit" :disabled="change.processing">{{ change.processing?'Saving…':'Save enrollment change' }}</button></div></form></section></div>
</DashboardLayout>
</template>
